import sys

def main():
    s = sys.stdin.read().split()[0]
    out = []
    val = 0
    in_run = False
    for ch in s:
        if ch == '0' or ch == '1':
            val = val * 2 + (ord(ch) - 48)
            in_run = True
        else:
            if in_run:
                out.append(str(val))
                val = 0
                in_run = False
            out.append(ch)
    if in_run:
        out.append(str(val))
    print(''.join(out))

