def gen(rng):
    def piece(maxrun):
        return ''.join(rng.choice('01') for _ in range(rng.randint(1, maxrun)))
    def build(n, maxrun, pdigits):
        out = []
        total = 0
        while total < n:
            if rng.random() < pdigits:
                p = piece(maxrun)
            else:
                p = ''.join(rng.choice('abcdefghijklmnopqrstuvwxyz') for _ in range(rng.randint(1, 4)))
            out.append(p)
            total += len(p)
        return ''.join(out)[:n]
    tests = ['a10101b001c11', '110abc111', 'x0y1', '0', '1', 'a', '000', '1' * 60, '0' * 60, 'z' + '1' * 60 + 'z', '1' * 60 + 'a' + '1' * 59, 'abc', '101', 'a0b0c0', '01a10']
    for n in (4, 6, 9, 15, 25, 40, 80):
        for _ in range(3):
            tests.append(build(n, 8, 0.5))
    # alternating letter/digit: many tiny runs
    tests.append(''.join(rng.choice('abc') + rng.choice('01') for _ in range(50000)))
    # long runs separated by single letters
    out = []
    total = 0
    while total < 100000:
        p = ''.join(rng.choice('01') for _ in range(60))
        out.append(p + 'q')
        total += 61
    tests.append(''.join(out)[:100000])
    tests.append('1' * 59 + 'a')
    tests.append(build(100000, 60, 0.6))
    tests.append(''.join(rng.choice('abcdefghijklmnopqrstuvwxyz') for _ in range(100000)))
    return tests

